  /(?:^|\s)(?:o\s+)?(?:te|le)\s+gustar[íi]a\s+cotizar\s+una\s+cantidad\s+espec[íi]fica\s*\??/gi,
  /(?:^|\s)(?:o\s+)?quieres?\s+cotizar\s+una\s+cantidad\s+espec[íi]fica\s*\??/gi,
