// ── E6 · Segmentar en bloques atómicos vs libres ──────────────────────────
const RE_COTIZ_ABRE = /(?:^|\s)cotizaci[óo]n\s*:\s*$|⏳|7 DIAS DE PROMO/i;
const RE_COTIZ_LINEA = /x\s*\$|^\s*\*?(Total|Env[íi]o|Anticipo|Subtotal)\*?\s*[:(]/i;
