const RE_SIETE_LINEA = /^\s*\d+[.)]\s|MUESTRA DIGITAL|PAGO FINAL|FOTO DEL PRODUCTO|COTIZACION de los|ANTICIPO para desarrollar|SENCILLOS PASOS/i;
